import math
from collections import Counter

def get_prime_factorization(num):
    factors = Counter()
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors[d] += 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] += 1
    return factors

def count_distinct_prime_factors(n):
    if n <= 0:
        return 0
    return len(get_prime_factorization(n))

TARGET_DIVISOR = 2023
N_MAX = 30

print(f"--- Testing n=1 to n={N_MAX} ---")

for n in range(1, N_MAX + 1):
    try:
        n_factorial = math.factorial(n)

        # 1. Check if K = n! / 2023 is an integer
        if n_factorial % TARGET_DIVISOR == 0:
            K = n_factorial // TARGET_DIVISOR

            # 2. Calculate omega(K)
            omega_K = count_distinct_prime_factors(K)

            # 3. Check the condition omega(K) <= 11
            is_condition_met = omega_K <= 11

            print(f"n={n}: K is integer. omega(K) = {omega_K}. Condition met: {is_condition_met}")
        else:
            print(f"n={n}: K is NOT an integer (n! not divisible by {TARGET_DIVISOR}).")

    except OverflowError:
        print(f"n={n}: Factorial too large to compute accurately.")

def count_primes(n):
    """Counts the number of primes less than or equal to n (pi(n))."""
    if n < 2:
        return 0
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    count = sum(is_prime[2:n+1])
    return count

# Calculate P(n) for n in the range [34, 50]
pi_values = {}
for n in range(34, 51):
    pi_values[n] = count_primes(n)

print("P(n) values for n in [34, 50]:")
print(pi_values)

def prime_count(n):
    primes = []
    is_prime = [True] * (n + 1)
    if n >= 0:
        is_prime[0] = False
    if n >= 1:
        is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    count = 0
    for i in range(2, n + 1):
        if is_prime[i]:
            count += 1
    return count

for n in range(34, 55):
